import * as THREE from 'three';
import {BUMPER as C} from './bumper-layout.js';
// This room has one fixed main-camera framing. Decorative rear canopy is not a
// reason to shrink the full-size actor. Fitting runs on entry/resize, never a RAF.
const boxes=[[-C.halfX-.17,C.halfX+.17,.02,.55,-C.halfZ-.17,C.halfZ+.17],[-C.halfX+C.radius-.66,C.halfX-C.radius+.66,C.rootY+.14,C.rootY+1.59,-C.halfZ+C.radius-.7,C.halfZ-C.radius+.7],[C.dock.x-.66,C.dock.x+.66,.05,2.34,C.dock.z+.35,C.dock.z+4.05],[-2.1,-.7,.05,1.7,4.15,5.35]];
function readRect(e){if(!e||e.hidden)return null;const style=globalThis.getComputedStyle?.(e)??e.ownerDocument?.defaultView?.getComputedStyle?.(e);if(style&&(style.display==='none'||style.visibility==='hidden'||style.visibility==='collapse'))return null;return(e.getClientRects?.().length??1)?e.getBoundingClientRect?.():null;}
function visibleRect(stage,selector){return readRect(stage.querySelector?.(selector));}
function visibleDocumentRect(selector){return readRect(globalThis.document?.querySelector?.(selector));}
export function activityNoteInsets(stage,note=visibleRect(stage,'#activity-note')){if(!note)return{top:0,bottom:0};const r=stage.getBoundingClientRect?.()??{top:0},middle=(note.top+note.bottom)/2-r.top,h=stage.clientHeight;return middle<h/2?{top:Math.max(0,note.bottom-r.top+12),bottom:0}:{top:0,bottom:Math.max(0,r.top+h-note.top+12)};}
// Expanded overlays can exceed a short viewport. Float excess guidance/control
// padding in that case, but keep at least 160px for a readable subject frame.
export function boundSafeInsets(top,bottom,height,baseTop,minUsable=160){let excess=top+bottom-Math.max(0,height-minUsable);if(excess<=0)return{top,bottom};const fromGuidance=Math.min(excess,Math.max(0,top-baseTop));top-=fromGuidance;excess-=fromGuidance;if(excess>0)bottom=Math.max(0,bottom-excess);return{top,bottom};}
export function bumperSafeArea(stage){const w=stage.clientWidth,h=stage.clientHeight,r=stage.getBoundingClientRect?.()??{left:0,top:0,right:w,bottom:h},rect=s=>visibleRect(stage,s),bar=visibleDocumentRect('.topbar'),tools=rect('.scene-tools'),guide=rect('#activity-note'),panel=rect('.bumper-controls'),action=rect('.action-area'),baseTop=Math.max(24,(bar?.bottom??81)-r.top+12,(tools?.bottom??0)-r.top+12);
 const footer=visibleDocumentRect('footer');
 if(w>h&&h<=520){const left=Math.max(180,(panel?.right??r.left+168)-r.left+12),right=Math.max(168,r.right-(action?.left??r.right-156)+12),noteOverlap=guide&&guide.right>r.left+left&&guide.left<r.right-right,note=noteOverlap?activityNoteInsets(stage,guide):{top:0,bottom:0},top=Math.max(baseTop,note.top),bottom=Math.max(42,r.bottom-(footer?.top??r.bottom)+12,note.bottom),bounded=boundSafeInsets(top,bottom,h,baseTop);return{left,right,...bounded};}
 const note=activityNoteInsets(stage,guide),top=Math.max(baseTop,note.top),lower=[panel?.top,action?.top,note.bottom?guide?.top:undefined].filter(Number.isFinite),bottom=Math.max(208,...lower.map(y=>r.bottom-y+12)),bounded=boundSafeInsets(top,bottom,h,baseTop);return{left:12,right:12,...bounded};
}
export function fitBumperCamera(camera,{width,height},padding){if(width<=0||height<=0)return;camera.updateMatrixWorld(true);const v=new THREE.Vector3();let l=Infinity,r=-Infinity,b=Infinity,t=-Infinity;for(const box of boxes)for(const x of[box[0],box[1]])for(const y of[box[2],box[3]])for(const z of[box[4],box[5]]){v.set(x,y,z).applyMatrix4(camera.matrixWorldInverse);l=Math.min(l,v.x);r=Math.max(r,v.x);b=Math.min(b,v.y);t=Math.max(t,v.y);}const p=padding??{left:12,right:12,top:93,bottom:208},pixels=Math.max(1,Math.min((width-p.left-p.right)/(r-l),(height-p.top-p.bottom)/(t-b)))/1.01,cx=(l+r)/2+(p.right-p.left)/(2*pixels),cy=(t+b)/2+(p.top-p.bottom)/(2*pixels);Object.assign(camera,{left:cx-width/(2*pixels),right:cx+width/(2*pixels),top:cy+height/(2*pixels),bottom:cy-height/(2*pixels),near:.1,far:200});camera.updateProjectionMatrix();}
